export interface MatchEvaluation {
  matchedName: 'Sur' | 'Mon' | 'Mith' | 'Thiru' | null;
  confidence: number; // 0 - 100
  allScores: Record<'Sur' | 'Mon' | 'Mith' | 'Thiru', number>; // 0 - 100
  isRecognized: boolean;
}

/**
 * Evaluates a probe image / canvas against the 4 trained profiles (Sur, Mon, Mith, Thiru)
 */
export function evaluateBiometrics(canvas: HTMLCanvasElement): MatchEvaluation {
  const w = canvas.width;
  const h = canvas.height;
  if (!w || !h) {
    return {
      matchedName: null,
      confidence: 0,
      allScores: { Sur: 0, Mon: 0, Mith: 0, Thiru: 0 },
      isRecognized: false,
    };
  }

  const offscreen = document.createElement('canvas');
  offscreen.width = 48;
  offscreen.height = 48;
  const octx = offscreen.getContext('2d', { willReadFrequently: true });
  if (!octx) {
    return {
      matchedName: null,
      confidence: 0,
      allScores: { Sur: 0, Mon: 0, Mith: 0, Thiru: 0 },
      isRecognized: false,
    };
  }

  // Multi-scale candidate bounding boxes (simulating face in center / guide frame)
  const boxes = [
    { x: 0.15, y: 0.15, w: 0.70, h: 0.70 },
    { x: 0.20, y: 0.20, w: 0.60, h: 0.60 },
    { x: 0.10, y: 0.10, w: 0.80, h: 0.80 },
    { x: 0.00, y: 0.00, w: 1.00, h: 1.00 },
    { x: 0.15, y: 0.08, w: 0.70, h: 0.70 },
    { x: 0.15, y: 0.22, w: 0.70, h: 0.70 },
  ];

  const bestScores: Record<'Sur' | 'Mon' | 'Mith' | 'Thiru', number> = {
    Sur: 0,
    Mon: 0,
    Mith: 0,
    Thiru: 0,
  };

  const names: ('Sur' | 'Mon' | 'Mith' | 'Thiru')[] = ['Sur', 'Mon', 'Mith', 'Thiru'];

  for (const box of boxes) {
    const sx = Math.max(0, Math.floor(w * box.x));
    const sy = Math.max(0, Math.floor(h * box.y));
    const sw = Math.min(w - sx, Math.floor(w * box.w));
    const sh = Math.min(h - sy, Math.floor(h * box.h));
    if (sw <= 10 || sh <= 10) continue;

    octx.clearRect(0, 0, 48, 48);
    octx.drawImage(canvas, sx, sy, sw, sh, 0, 0, 48, 48);
    const imgData = octx.getImageData(0, 0, 48, 48);
    const data = imgData.data;

    // 1. Grayscale zero-mean unit-variance
    const grays = new Float32Array(2304);
    let sum = 0;
    for (let i = 0; i < 2304; i++) {
      const r = data[i * 4];
      const g = data[i * 4 + 1];
      const b = data[i * 4 + 2];
      const gray = 0.299 * r + 0.587 * g + 0.114 * b;
      grays[i] = gray;
      sum += gray;
    }
    const mean = sum / 2304;
    let sqSum = 0;
    for (let i = 0; i < 2304; i++) {
      const diff = grays[i] - mean;
      sqSum += diff * diff;
    }
    const std = Math.sqrt(sqSum / 2304) + 1e-6;

    // 2. Zone color features (3 vertical zones)
    const zoneStats: number[] = [];
    for (let z = 0; z < 3; z++) {
      const startRow = z * 16;
      const endRow = (z + 1) * 16;
      let rSum = 0, gSum = 0, bSum = 0;
      const pixelCount = 16 * 48;
      for (let r = startRow; r < endRow; r++) {
        for (let c = 0; c < 48; c++) {
          const idx = (r * 48 + c) * 4;
          rSum += data[idx];
          gSum += data[idx + 1];
          bSum += data[idx + 2];
        }
      }
      const rMean = rSum / pixelCount;
      const gMean = gSum / pixelCount;
      const bMean = bSum / pixelCount;

      let rSq = 0, gSq = 0, bSq = 0;
      for (let r = startRow; r < endRow; r++) {
        for (let c = 0; c < 48; c++) {
          const idx = (r * 48 + c) * 4;
          rSq += (data[idx] - rMean) ** 2;
          gSq += (data[idx + 1] - gMean) ** 2;
          bSq += (data[idx + 2] - bMean) ** 2;
        }
      }
      zoneStats.push(
        rMean, gMean, bMean,
        Math.sqrt(rSq / pixelCount),
        Math.sqrt(gSq / pixelCount),
        Math.sqrt(bSq / pixelCount)
      );
    }

    // Evaluate against each trained profile
    for (const name of names) {
      const profile = TRAINED_PROFILES[name];
      if (!profile) continue;

      // ZNCC structural match
      let dot = 0;
      for (let i = 0; i < 2304; i++) {
        const normVal = (grays[i] - mean) / std;
        dot += normVal * profile.template[i];
      }
      const zncc = Math.max(0, dot / 2304);

      // Color distance
      let colDistSq = 0;
      for (let i = 0; i < 18; i++) {
        colDistSq += (zoneStats[i] - profile.colorZones[i]) ** 2;
      }
      const colDist = Math.sqrt(colDistSq);
      const colSim = Math.max(0, 1 - (colDist / 180));

      const score = zncc * 0.70 + colSim * 0.30;
      if (score > bestScores[name]) {
        bestScores[name] = score;
      }
    }
  }

  // Determine top match
  let topName: 'Sur' | 'Mon' | 'Mith' | 'Thiru' | null = null;
  let topScore = 0;
  let runnerUpScore = 0;

  for (const name of names) {
    const s = bestScores[name];
    if (s > topScore) {
      runnerUpScore = topScore;
      topScore = s;
      topName = name;
    } else if (s > runnerUpScore) {
      runnerUpScore = s;
    }
  }

  // Precision threshold: A confident match must exceed 0.65 (65%) and have a distinct margin
  const margin = topScore - runnerUpScore;
  const isRecognized = topScore >= 0.65 || (topScore >= 0.58 && margin >= 0.12);

  return {
    matchedName: isRecognized ? topName : null,
    confidence: Math.round(topScore * 100),
    allScores: {
      Sur: Math.round(bestScores.Sur * 100),
      Mon: Math.round(bestScores.Mon * 100),
      Mith: Math.round(bestScores.Mith * 100),
      Thiru: Math.round(bestScores.Thiru * 100),
    },
    isRecognized,
  };
}
